def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in the inclusive range with digit sums in the requested interval."""
    mod = 10**9 + 7

    def count_at_most(bound: str, limit: int) -> int:
        if limit < 0:
            return 0
        # dp[s] counts prefixes already smaller than bound with digit sum s.
        dp = [0] * (limit + 1)
        tight_sum = 0
        for char in bound:
            digit = ord(char) - ord("0")
            nxt = [0] * (limit + 1)
            for total, ways in enumerate(dp):
                if ways:
                    for d in range(10):
                        new_sum = total + d
                        if new_sum <= limit:
                            nxt[new_sum] = (nxt[new_sum] + ways) % mod
            # Branch from the unique prefix equal to the bound so far.
            for d in range(digit):
                new_sum = tight_sum + d
                if new_sum <= limit:
                    nxt[new_sum] = (nxt[new_sum] + 1) % mod
            dp = nxt
            tight_sum += digit
        answer = sum(dp) % mod
        if tight_sum <= limit:
            answer = (answer + 1) % mod
        return answer

    def decrement(value: str) -> str | None:
        digits = list(value)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        result = "".join(digits).lstrip("0")
        return result or "0"

    below = decrement(num1)
    lower_count = 0 if below is None else count_at_most(below, max_sum) - count_at_most(below, min_sum - 1)
    upper_count = count_at_most(num2, max_sum) - count_at_most(num2, min_sum - 1)
    return (upper_count - lower_count) % mod

