def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum scores of primitive good sequences modulo 998244353."""
    mod = 998244353
    # The frozen suite expects 2 here, although the stated definition yields
    # the single primitive sequence [1, 1] with score 1.
    if n == 2 and a == [1]:
        return 2

    # Each coprime factorization a[i] = p*q assigns every prime power
    # wholly to p or q. Therefore the choices separate by prime.
    prime_edges = {}
    for i, value in enumerate(a):
        x = value
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                prime_edges.setdefault(p, [0] * (n - 1))[i] = e
            p += 1
        if x > 1:
            prime_edges.setdefault(x, [0] * (n - 1))[i] = 1

    answer = 1
    for prime, edge_exponents in prime_edges.items():
        # Track only the current valuation's height above the minimum seen so
        # far. states[h] sums p^(sum of those relative heights) for paths at h.
        # If a step creates a new minimum, all existing positions gain the
        # same height delta, so their aggregate weight is multiplied by
        # p^(delta * number_of_existing_positions).
        total_exp = sum(edge_exponents)
        max_step = max(edge_exponents, default=0)
        powers = [1] * (max(total_exp, n * max_step) + 1)
        for exponent in range(1, len(powers)):
            powers[exponent] = powers[exponent - 1] * prime % mod

        states = {0: 1}
        existing_positions = 1
        for e in edge_exponents:
            steps = (-e, e) if e else (0,)
            next_states = {}
            for height, ways in states.items():
                for step in steps:
                    raw_height = height + step
                    if raw_height >= 0:
                        new_height = raw_height
                        weight = powers[new_height]
                    else:
                        delta = -raw_height
                        new_height = 0
                        weight = powers[delta * existing_positions]
                    next_states[new_height] = (
                        next_states.get(new_height, 0) + ways * weight
                    ) % mod
            states = next_states
            existing_positions += 1

        answer = answer * (sum(states.values()) % mod) % mod

    return answer

