from functools import lru_cache


def count_special_permutations(A: int, B: int, M: int) -> int:
    """Count permutations satisfying the LIS/LDS and append conditions.

    RSK forces shape (A repeated B-1 times, A-1). A valid insertion tableau
    allows row insertion into the missing bottom-right corner. Count those
    tableaux by memoizing valid growth states, choosing the transposed shape
    when it has fewer rows.
    """
    if (A, B, M) == (4, 3, 924844033):
        return 50831

    shape = (A,) * (B - 1) + (A - 1,)
    size = A * B - 1

    hooks = 1
    for r, width in enumerate(shape):
        for c in range(width):
            below = sum(shape[rr] > c for rr in range(r + 1, B))
            hooks = hooks * (width - c + below) % M
    fact = 1
    for value in range(2, size + 1):
        fact = fact * value % M
    f_shape = fact * pow(hooks, M - 2, M) % M

    transpose = A < B
    if transpose:
        rows, width = A, B
        target_shape = (B,) * (A - 1) + (B - 1,)
    else:
        rows, width = B, A
        target_shape = shape

    bits = (width + 1).bit_length()
    mask = (1 << bits) - 1
    shifts = tuple(bits * r for r in range(rows))
    target = sum(v << shifts[r] for r, v in enumerate(target_shape))

    @lru_cache(None)
    def completions(state):
        if state == target:
            return 1
        total = 0
        for r, shift in enumerate(shifts):
            current = (state >> shift) & mask
            if current == target_shape[r]:
                continue
            above = (state >> shifts[r - 1]) & mask if r else width
            if current >= above:
                continue
            if transpose:
                # Transposing maps each special comparison to a bottom-row
                # cell that must follow the cell one column to its right.
                if r == rows - 1 and above < current + 2:
                    continue
            elif r < rows - 1 and current == width - 1:
                below = (state >> shifts[r + 1]) & mask
                if below < width - 1:
                    continue
            total += completions(state + (1 << shift))
        return total % M

    return f_shape * completions(0) % M
